CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE IF NOT EXISTS centers (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, city text NOT NULL, state text NOT NULL, status text NOT NULL CHECK (status IN ('planned','open','paused')), operator_name text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS programs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), slug text UNIQUE NOT NULL, title text NOT NULL, track text NOT NULL, level text NOT NULL, duration text NOT NULL, description text NOT NULL, published boolean NOT NULL DEFAULT false);
CREATE TABLE IF NOT EXISTS leads (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), kind text NOT NULL CHECK (kind IN ('student','enterprise','franchise','instructor','employer')), name text NOT NULL, email text NOT NULL, city text, message text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS organizations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name text NOT NULL, kind text NOT NULL CHECK (kind IN ('enterprise','franchise','academy','employer')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS learners (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, display_name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS cohorts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), program_id uuid NOT NULL REFERENCES programs(id), center_id uuid REFERENCES centers(id), starts_at timestamptz, capacity integer CHECK (capacity > 0), status text NOT NULL DEFAULT 'draft');
CREATE TABLE IF NOT EXISTS enrollments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), learner_id uuid NOT NULL REFERENCES learners(id), cohort_id uuid NOT NULL REFERENCES cohorts(id), status text NOT NULL DEFAULT 'enrolled', UNIQUE(learner_id,cohort_id));
CREATE TABLE IF NOT EXISTS credentials (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), learner_id uuid NOT NULL REFERENCES learners(id), program_id uuid NOT NULL REFERENCES programs(id), issuer text NOT NULL DEFAULT 'HybridGenAI Academy', verification_token uuid UNIQUE NOT NULL DEFAULT gen_random_uuid(), issued_at timestamptz NOT NULL DEFAULT now(), revoked_at timestamptz);
CREATE TABLE IF NOT EXISTS job_postings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), employer_id uuid NOT NULL REFERENCES organizations(id), title text NOT NULL, location text, application_url text, status text NOT NULL DEFAULT 'draft', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS job_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), posting_id uuid NOT NULL REFERENCES job_postings(id), learner_id uuid NOT NULL REFERENCES learners(id), status text NOT NULL DEFAULT 'submitted', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS franchise_applications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), lead_id uuid UNIQUE NOT NULL REFERENCES leads(id), preferred_city text NOT NULL, review_status text NOT NULL DEFAULT 'new');
